pub(super) fn should_log_frequency(freq_idx: usize, total: usize) -> bool {
    let completed = freq_idx + 1;
    completed == 1 || completed == total || completed.is_multiple_of((total / 10).max(1))
}

pub(super) fn duration_ms(duration: Duration) -> f64 {
    duration.as_secs_f64() * 1000.0
}

pub(super) fn iteration_spike(current: usize, recent: &[usize]) -> bool {
    if recent.len() < 3 {
        return false;
    }
    let mut window = recent[recent.len().saturating_sub(5)..].to_vec();
    window.sort_unstable();
    let median = window[window.len() / 2];
    median > 0 && current > median + median / 2
}

pub(super) fn shifted_laplacian_amg_config() -> AmgConfig {
    let mut config = AmgConfig::for_parallel();
    config.smoother = AmgSmoother::Chebyshev;
    config.strong_threshold = 0.5;
    config
}

pub(super) fn artificial_schwarz_interface_faces(mesh: &Mesh, planes: &[f64]) -> Vec<Vec<usize>> {
    if planes.is_empty() {
        return Vec::new();
    }

    let mut face_count: HashMap<Vec<usize>, (Vec<usize>, usize)> = HashMap::new();
    for elem in &mesh.elements {
        for face in element_faces(elem.element_type, elem.vertices()) {
            let mut key = face.clone();
            key.sort_unstable();
            face_count
                .entry(key)
                .and_modify(|(_, count)| *count += 1)
                .or_insert((face, 1));
        }
    }

    face_count
        .into_values()
        .filter_map(|(face, count)| {
            if count == 2 && face_lies_on_any_x_plane(mesh, &face, planes) {
                Some(face)
            } else {
                None
            }
        })
        .collect()
}

pub(super) fn element_faces(element_type: ElementType, verts: &[usize]) -> Vec<Vec<usize>> {
    match element_type {
        ElementType::Triangle => vec![
            vec![verts[0], verts[1]],
            vec![verts[1], verts[2]],
            vec![verts[2], verts[0]],
        ],
        ElementType::Quadrilateral => vec![
            vec![verts[0], verts[1]],
            vec![verts[1], verts[2]],
            vec![verts[2], verts[3]],
            vec![verts[3], verts[0]],
        ],
        ElementType::Tetrahedron => vec![
            vec![verts[0], verts[1], verts[2]],
            vec![verts[0], verts[1], verts[3]],
            vec![verts[0], verts[2], verts[3]],
            vec![verts[1], verts[2], verts[3]],
        ],
        ElementType::Hexahedron => vec![
            vec![verts[0], verts[1], verts[2], verts[3]],
            vec![verts[4], verts[5], verts[6], verts[7]],
            vec![verts[0], verts[1], verts[5], verts[4]],
            vec![verts[2], verts[3], verts[7], verts[6]],
            vec![verts[0], verts[3], verts[7], verts[4]],
            vec![verts[1], verts[2], verts[6], verts[5]],
        ],
    }
}

pub(super) fn face_lies_on_any_x_plane(mesh: &Mesh, face: &[usize], planes: &[f64]) -> bool {
    planes.iter().any(|&plane| {
        face.iter()
            .all(|&node| (mesh.nodes[node].x - plane).abs() <= 1e-8)
    })
}

pub(super) fn retry_initial_guess<'a>(
    failed_current_frequency: Option<&'a [Complex64]>,
    previous_frequency: Option<&'a [Complex64]>,
) -> Option<&'a [Complex64]> {
    failed_current_frequency.or(previous_frequency)
}

pub(super) fn true_relative_residual(
    operator: &CsrMatrix<Complex64>,
    x: &[Complex64],
    rhs: &[Complex64],
) -> f64 {
    let residual_sq: f64 = residual_vector(operator, x, rhs)
        .iter()
        .map(|r| r.norm_sqr())
        .sum();
    let rhs_sq: f64 = rhs.iter().map(|b| b.norm_sqr()).sum();
    if rhs_sq > 0.0 {
        (residual_sq / rhs_sq).sqrt()
    } else {
        residual_sq.sqrt()
    }
}

pub(super) fn residual_vector(
    operator: &CsrMatrix<Complex64>,
    x: &[Complex64],
    rhs: &[Complex64],
) -> Vec<Complex64> {
    let mut ax = vec![Complex64::new(0.0, 0.0); rhs.len()];
    operator.apply_into(x, &mut ax);
    rhs.iter().zip(ax).map(|(b, ax)| *b - ax).collect()
}

/// Collect all mesh node indices on a given boundary marker.
pub(super) fn collect_boundary_nodes(mesh: &Mesh, marker: i32) -> HashSet<usize> {
    let mut nodes = HashSet::new();
    for face in &mesh.boundaries {
        if face.marker == marker {
            for &n in &face.nodes {
                nodes.insert(n);
            }
        }
    }
    nodes
}

/// Bounding box of the mesh (axis-aligned). Used to generate image sources for
/// near-wall input sources so their Gaussian envelopes don't lose strength to
/// boundary truncation.
pub(super) fn mesh_aabb(mesh: &Mesh) -> ([f64; 3], [f64; 3]) {
    let mut lo = [f64::INFINITY; 3];
    let mut hi = [f64::NEG_INFINITY; 3];
    for n in &mesh.nodes {
        let p = [n.x, n.y, n.z];
        for axis in 0..3 {
            if p[axis] < lo[axis] {
                lo[axis] = p[axis];
            }
            if p[axis] > hi[axis] {
                hi[axis] = p[axis];
            }
        }
    }
    (lo, hi)
}

/// For a given source position, return the set of *effective* source positions
/// that should be summed to compensate for Gaussian truncation at the mesh
/// boundaries. Each near wall (within `cutoff` of the source on its axis)
/// contributes an image position by reflection; up to 8 effective positions
/// for a corner source within `cutoff` of three walls. Walls are Neumann at
/// the volume-RHS level (the absorbing Robin term is added separately as a
/// boundary mass), so reflection across them is the correct image.
pub(super) fn image_positions(p: Point3D, aabb: ([f64; 3], [f64; 3]), cutoff: f64) -> Vec<Point3D> {
    let (lo, hi) = aabb;
    let mut xs = vec![p.x];
    if (p.x - lo[0]).abs() < cutoff {
        xs.push(2.0 * lo[0] - p.x);
    }
    if (p.x - hi[0]).abs() < cutoff {
        xs.push(2.0 * hi[0] - p.x);
    }
    let mut ys = vec![p.y];
    if (p.y - lo[1]).abs() < cutoff {
        ys.push(2.0 * lo[1] - p.y);
    }
    if (p.y - hi[1]).abs() < cutoff {
        ys.push(2.0 * hi[1] - p.y);
    }
    let mut zs = vec![p.z];
    if (p.z - lo[2]).abs() < cutoff {
        zs.push(2.0 * lo[2] - p.z);
    }
    if (p.z - hi[2]).abs() < cutoff {
        zs.push(2.0 * hi[2] - p.z);
    }
    let mut out = Vec::with_capacity(xs.len() * ys.len() * zs.len());
    for &xi in &xs {
        for &yi in &ys {
            for &zi in &zs {
                out.push(Point3D::new(xi, yi, zi));
            }
        }
    }
    out
}

pub(super) fn point_aabb_distance_sq(point: Point3D, coords: &[[f64; 3]]) -> f64 {
    let mut min = [f64::INFINITY; 3];
    let mut max = [f64::NEG_INFINITY; 3];
    for coord in coords {
        for axis in 0..3 {
            min[axis] = min[axis].min(coord[axis]);
            max[axis] = max[axis].max(coord[axis]);
        }
    }

    let p = [point.x, point.y, point.z];
    let mut dist_sq = 0.0;
    for axis in 0..3 {
        let d = if p[axis] < min[axis] {
            min[axis] - p[axis]
        } else if p[axis] > max[axis] {
            p[axis] - max[axis]
        } else {
            0.0
        };
        dist_sq += d * d;
    }
    dist_sq
}

/// Store interpolated listener pressures. Source directivity is already part
/// of the FEM right-hand side and must not be applied again at the receiver.
pub(super) fn store_listener_pressures(
    _listening_positions: &[Point3D],
    lp_pressures: &[Complex64],
    _source: &Source,
    _freq: f64,
    out_pressures: &mut [Vec<Complex64>],
    freq_idx: usize,
) {
    for (lp_idx, &pressure) in lp_pressures.iter().enumerate() {
        out_pressures[lp_idx][freq_idx] = pressure;
    }
}
